class Solution {
  private static int pairs(int[] c, int w) {
    int a = 0, m = 0;
    for (int v : c) {
      a += v;
      m = Math.max(m, v);
    }
    return Math.min(Math.min((a + w) / 2, a + w - m), a);
  }

  public int score(String[] cards, char x) {
    int[] first = new int[26], second = new int[26];
    int both = 0;
    for (String s : cards) {
      boolean f = s.charAt(0) == x, g = s.charAt(1) == x;
      if (f && g) both++;
      else if (f) first[s.charAt(1) - 'a']++;
      else if (g) second[s.charAt(0) - 'a']++;
    }
    int best = 0;
    for (int w = 0; w <= both; w++)
      best = Math.max(best, pairs(first, w) + pairs(second, both - w));
    return best;
  }
}
